export type IconKey = keyof typeof ICONS;

// The array overload is listed last, so its element type is the theme colour name union.
type ThemeColor = Parameters<typeof useThemeColor>[0][number];

/**
 * A Gravity UI icon by name (PascalCase, as in fixtures and the web Icon). Decorative unless labelled.
 * Colour: a theme token via "tone" (default "foreground"), or an explicit "color".
 */
export function Icon({
  name,
  size = 16,
  tone = "foreground",
  color,
  accessibilityLabel,
}: {
  name: string;
  size?: number;
  tone?: ThemeColor;
  color?: string;
  accessibilityLabel?: string;
}) {
  const themed = useThemeColor(tone);
  const paths = ICONS[name];
  if (!paths) return null;
  const fill = color ?? themed;
  return (
    <Svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      accessible={!!accessibilityLabel}
      accessibilityLabel={accessibilityLabel}
    >
      {paths.map((p) => (
        <Path key={p.d} d={p.d} fill={fill} fillRule={p.fillRule} clipRule={p.clipRule} opacity={p.opacity} />
      ))}
    </Svg>
  );
}
